import * as React from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import data from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import ImageModal, { type ImageItem } from "../components/ImageModal";
import Ornament from "../components/ornament";
import SEO from "../components/seo";

const userData: UserProfile = data;

const galleryCollections = [
  {
    id: "facade",
    folder: "facade",
    icon: "/gallery/thumb_gallery_1.png",
    titleKey: "gallery.facade",
    files: [
      "gallery_1.png", 
      "gallery_2.png", 
      "gallery_3.png", 
      "gallery_4.png", 
      "gallery_5.png"
    ],
  },
  {
    id: "lobby",
    icon: "/gallery/thumb_gallery_2.png",
    titleKey: "gallery.lobby",
    files: ["thumb_gallery_2.png"],
  },
  {
    id: "roof",
    icon: "/gallery/thumb_gallery_3.png",
    titleKey: "gallery.roof",
    files: ["thumb_gallery_3.png"],
  },
  {
    id: "multipurposeRoom",
    icon: "/gallery/thumb_gallery_4.png",
    titleKey: "gallery.multipurposeRoom",
    files: ["thumb_gallery_4.png"],
  },
  {
    id: "exerciseRoom",
    icon: "/gallery/thumb_gallery_5.png",
    titleKey: "gallery.exerciseRoom",
    files: ["thumb_gallery_5.png"],
  },
  {
    id: "streetView",
    icon: "/gallery/thumb_gallery_6.png",
    titleKey: "gallery.streetView",
    files: ["thumb_gallery_6.png"],
  },
  {
    id: "entrance",
    icon: "/gallery/thumb_gallery_7.png",
    titleKey: "gallery.entrance",
    files: ["thumb_gallery_7.png"],
  },
  {
    id: "playRoom",
    icon: "/gallery/thumb_gallery_8.png",
    titleKey: "gallery.playRoom",
    files: ["thumb_gallery_8.png"],
  },
  {
    id: "otherFacilities",
    icon: "/gallery/thumb_gallery_9.png",
    titleKey: "gallery.otherFacilities",
    files: ["thumb_gallery_9.png"],
  },

];

const GalleryPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  const [modalImages, setModalImages] = React.useState<ImageItem[]>([]);
  const [pendingOpen, setPendingOpen] = React.useState(false);
  const openModalRef = React.useRef<((startIndex?: number) => void) | null>(
    null
  );

  const openGallery = (images: ImageItem[]) => {
    setModalImages(images);
    setPendingOpen(true);
  };

  React.useEffect(() => {
    if (!pendingOpen || modalImages.length === 0) return;
    if (!openModalRef.current) return;
    openModalRef.current(0);
    setPendingOpen(false);
  }, [pendingOpen, modalImages]);

  const galleries = galleryCollections.map((collection) => {
    const label = t(collection.titleKey) as string;
    const basePath = collection.folder
      ? `/gallery/${collection.folder}`
      : "/gallery";
    const images = collection.files.map((file, index) => ({
      src: encodeURI(`${basePath}/${file}`),
      alt: `${label} ${index + 1}`,
      caption: label,
    }));

    return { ...collection, label, images };
  });

  return (
    <Layout data={userData}>
      <SEO
        data={userData}
        titleKey="gallery.metaTitle"
        descriptionKey="gallery.metaDescription"
        pathname="/gallery/"
        schemaType="ProfessionalService"
      />
      <section>
        <ImageModal
          images={modalImages}
          trigger={(open) => {
            openModalRef.current = open;
            return null;
          }}
        />

        <section className="text-terracota bg-beige px-12 py-6 mb-6 shadow-lg">

          <h2 className={styles.title}>{t("menu.gallery")}</h2>

        <article className="grid gap-1 md:grid-cols-3 w-3/4 mx-auto">
          {galleries.map((gallery, index) => (
            <button
              key={gallery.id}
              type="button"
              className={`group text-terracota flex w-full flex-col items-center px-6 py-4 text-center transition duration-200 hover:-translate-y-1 `}
              onClick={() => openGallery(gallery.images)}
            >
              <img
                src={gallery.icon}
                alt={gallery.label}
                className="mb-4 h-32 w-auto object-contain"
              />
              <span className="body_mobile sm:body_desk">{gallery.label}</span>
            </button>
          ))}
        </article>



          <figure className="flex justify-center mt-6">
            <Ornament className="w-96 text-terracota/60 rotate-180" />
          </figure>
        </section>

      </section>
    </Layout>
  );
};

export default GalleryPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  title: "h2_mobile sm:h2_desk text-center mb-6",
};
